CREATE TABLE IF NOT EXISTS gxa_sessions(token_hash varchar(64) PRIMARY KEY,user_id uuid NOT NULL,csrf_token varchar(80) NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS gxa_conversations(id uuid PRIMARY KEY,user_id uuid NOT NULL,title varchar(100) NOT NULL,active_task_id uuid,last_event_seq bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gxa_tasks(id uuid PRIMARY KEY,user_id uuid NOT NULL,conversation_id uuid NOT NULL REFERENCES gxa_conversations(id),status varchar(40) NOT NULL DEFAULT 'RUNNING',version bigint NOT NULL DEFAULT 0,state jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gxa_messages(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES gxa_conversations(id),run_id uuid,client_message_id uuid,role varchar(20) NOT NULL,content text NOT NULL,status varchar(20) NOT NULL DEFAULT 'COMPLETED',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conversation_id,client_message_id));
CREATE TABLE IF NOT EXISTS gxa_commands(id uuid PRIMARY KEY,user_id uuid NOT NULL,conversation_id uuid NOT NULL REFERENCES gxa_conversations(id),task_id uuid NOT NULL REFERENCES gxa_tasks(id),dedupe_key uuid NOT NULL,request_hash varchar(64) NOT NULL,payload jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'QUEUED',trace_id varchar(64) NOT NULL,session_hash varchar(64),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,conversation_id,dedupe_key));
CREATE TABLE IF NOT EXISTS gxa_events(conversation_id uuid NOT NULL REFERENCES gxa_conversations(id),event_seq bigint NOT NULL,task_id uuid,run_id uuid,type varchar(80) NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(conversation_id,event_seq));
CREATE INDEX IF NOT EXISTS ix_gxa_conversations_user ON gxa_conversations(user_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS ix_gxa_commands_status ON gxa_commands(status,created_at);
CREATE INDEX IF NOT EXISTS ix_gxa_events_task ON gxa_events(task_id,event_seq);
ALTER TABLE gxa_messages ADD COLUMN IF NOT EXISTS components jsonb NOT NULL DEFAULT '[]';
